import { useState } from "react";
import "./SignIn.css";

function Register() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [message, setMessage] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Reset states
    setMessage("");
    setIsSuccess(false);

    // Validation
    if (password !== confirmPassword) {
      setMessage("Parolele nu coincid!");
      return;
    }

    setIsLoading(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/register", {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Accept": "application/json"
        },
        body: JSON.stringify({ 
          name, 
          email, 
          password 
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Eroare la înregistrare");
      }

      // Success case
      setIsSuccess(true);
      setMessage("Înregistrare reușită! Datele au fost adăugate în baza de date.");
      
      // Clear form on success
      setName("");
      setEmail("");
      setPassword("");
      setConfirmPassword("");
      
    } catch (err) {
      console.error("Registration error:", err);
      setMessage(err.message || "Eroare la comunicarea cu serverul. Încearcă din nou.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="signin-container">
      <div className="signin-card">
        <h2 className="signin-title">Înregistrare</h2>
        <form onSubmit={handleSubmit} className="signin-form">
          <div className="form-group">
            <label htmlFor="name">Nume complet</label>
            <input
              id="name"
              type="text"
              placeholder="Introdu numele tău"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              placeholder="Introdu adresa de email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="password">Parolă</label>
            <input
              id="password"
              type="password"
              placeholder="Introdu parola"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              minLength="6"
            />
          </div>

          <div className="form-group">
            <label htmlFor="confirmPassword">Confirmă parola</label>
            <input
              id="confirmPassword"
              type="password"
              placeholder="Reintrodu parola"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
            />
          </div>
          
          <button 
            type="submit" 
            className="submit-btn"
            disabled={isLoading}
          >
            {isLoading ? 'Se încarcă...' : 'Înregistrează-te'}
          </button>
        </form>
        
        {message && (
          <div className={`message ${isSuccess ? "success" : "error"}`}>
            {message}
            {isSuccess && (
              <div style={{marginTop: '10px'}}>
                <a href="/signin" className="login-link">Autentifică-te acum</a>
              </div>
            )}
          </div>
        )}

        <div className="login-link">
          Ai deja cont? <a href="/signin">Autentifică-te</a>
        </div>
      </div>
    </div>
  );
}

export default Register;
